<?php

namespace Demandes\DemandesBundle\Repository;

use Demandes\DemandesBundle\TypeDemande;
use Doctrine\ORM\Query\Expr\Join;

/**
 * TypeDemandeRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TypeDemandeRepository extends \Doctrine\ORM\EntityRepository {

    public function findTypeDemande() {
        $subQueryBuilder = $this->getEntityManager()->createQueryBuilder();
        $subQuery = $subQueryBuilder
                ->select(['IDENTITY(tQ.typeDemande)'])
                ->from('DemandesBundle:Quota', 'tQ')
                ->getQuery()
                ->getArrayResult()
        ;
//dump($subQuery); die;
        $queryBuilder = $this->getEntityManager()->createQueryBuilder();
        $query = $queryBuilder
                ->select(['c'])
                ->from('DemandesBundle:TypeDemande', 'c')
                ->where($queryBuilder->expr()->notIn('c.id', ':subQuery'))
                ->setParameter('subQuery', $subQuery)

        ;
        return $query;
    }

    public function dateDebutFin($periode = null) {
        $date = new \DateTime();
        $mois = $date->format('m');
        switch ($periode) {
            //1 mois
            case 1:
                $dateDeb = $date->format('Y-m-01');
                $dateFin = $date->format('Y-m-t');
                break;
            //2 trimestre
            case 2:
                if ($mois < 4) {
                    $dateDeb = $date->format('Y-01-01');
                    $dateFin = $date->format('Y-03-t');
                } elseif ($mois < 7) {
                    $dateDeb = $date->format('Y-04-01');
                    $dateFin = $date->format('Y-06-t');
                } else if ($mois < 10) {
                    $dateDeb = $date->format('Y-07-01');
                    $dateFin = $date->format('Y-09-t');
                } else {
                    $dateDeb = $date->format('Y-10-01');
                    $dateFin = $date->format('Y-12-t');
                }
                break;
            //3 semestre
            case 3:
                if ($mois < 7) {
                    $dateDeb = $date->format('Y-01-01');
                    $dateFin = $date->format('Y-06-t');
                } else {
                    $dateDeb = $date->format('Y-07-01');
                    $dateFin = $date->format('Y-12-t');
                }

                break;
            //4 année
            case 4:
                $dateDeb = $date->format('Y-01-01');
                $dateFin = $date->format('Y-12-t');
                break;
            default :
                $dateDeb = null;
                $dateFin = null;
                break;
        }
        return $tab = [$dateDeb, $dateFin];
    }

    public function periodeQuota() {
        $liste = $this->getEntityManager()->createQueryBuilder()
                ->select('q.id, q.nbreQuota, q.nbreJoursAvant, IDENTITY(q.typeDemande) as type, IDENTITY(q.periode) as periode')
                ->from('DemandesBundle:Quota', 'q')
                ->getQuery()
                ->getArrayResult()
        ;
        foreach ($liste as $list) {


            //dump($mois);
            $dateDeb = null;
            $dateFin = null;
            if ($list['periode'] == 1) {
                $dateDeb = $this->dateDebutFin(1)[0];
                $dateFin = $this->dateDebutFin(1)[1];
            } elseif ($list['periode'] == 2) {
                $dateDeb = $this->dateDebutFin(2)[0];
                $dateFin = $this->dateDebutFin(2)[1];
            } elseif ($list['periode'] == 3) {
                $dateDeb = $this->dateDebutFin(3)[0];
                $dateFin = $this->dateDebutFin(3)[1];
            } elseif ($list['periode'] == 4) {
                $dateDeb = $this->dateDebutFin(4)[0];
                $dateFin = $this->dateDebutFin(4)[1];
            }
            $tab[$list['id']] = ['id' => $list['id'], 'periode' => $list['periode'], 'date_debut' => $dateDeb, 'date_fin' => $dateFin];
        }
        return $tab;
    }

   public function findTypeDemandePrive($matricule) {


        //////////////////////Vérification Demande en cours ////////////////
        $queryBuilder = $this->getEntityManager()->createQueryBuilder();
        $demandeEncours = $queryBuilder
                ->select(['IDENTITY(d.typeDemande)'])
                ->from('DemandesBundle:Demande', 'd')
                ->where('d.etatEncours = 0')
                ->andWhere('d.emmeteur = :Matricule')
                ->setParameter('Matricule', $matricule)
                ->getQuery()
                ->getArrayResult();
        ////////////Recuperation des quotas pour chaque type de demande qui en a un /////////////////////////////////
        $liste = $this->getEntityManager()->createQueryBuilder()
                ->select('q.id, q.nbreQuota, q.nbreJoursAvant, IDENTITY(q.typeDemande) as type, IDENTITY(q.periode) as periode')
                ->from('DemandesBundle:Quota', 'q')
                ->getQuery()
                ->getArrayResult()
        ;
        $demandeAboutit = null;
        foreach ($liste as $list) {


            //dump($list);

            $dateDeb = $this->dateDebutFin($list['periode'])[0];
            $dateFin = $this->dateDebutFin($list['periode'])[1];
            //dump($dateDeb);
           // dump($dateFin);

            $queryBuilder = $this->getEntityManager()->createQueryBuilder();

            $demandeAboutis = $queryBuilder
                    ->select(['IDENTITY(d.typeDemande) as type, IDENTITY(q.periode) as periode, count(d.id) as compter'])
                    ->from('DemandesBundle:Demande', 'd')
                    //->join('DemandesBundle:TypeDemande', 't', Join::WITH, 'd.typeDemande = t.id')
                    ->join('DemandesBundle:Quota', 'q', Join::WITH, 'd.typeDemande = q.typeDemande')
                    ->where('d.etatRepGrh = 1')// or d.etatRepGrh != 2
                    ->andWhere('d.emmeteur = :Matricule')
                    ->andWhere('d.datecreation BETWEEN :debut AND :fin')
                    ->andWhere('d.typeDemande = :Type')
                    ->groupBy('d.typeDemande')
                    ->setParameter('Matricule', $matricule)
                    ->setParameter('debut', $dateDeb)
                    ->setParameter('Type', $list['type'])
                    ->setParameter('fin', $dateFin)
                    ->getQuery()
                    ->getResult();

            if (($demandeAboutis) != null) {
                $demandeAboutit[] = ['type' => $demandeAboutis[0]['type'], 'periode' => $demandeAboutis[0]['periode'], 'compter' => $demandeAboutis[0]['compter'],];
            }//dump($demandeAboutis);
        }
        //////////////////Vérification Demande Aboutit(Validé) ///////////////////////
        /////////////
        if (count($demandeAboutit) == 0) {
            $demandeAboutit = [];
        }

        $array = [0];

        foreach ($demandeAboutit as $test) {
            //dump($test['type']);
            //dump($test['compter']);
            $queryBuilder = $this->getEntityManager()->createQueryBuilder();
            $quota = $queryBuilder
                    ->select('q.nbreQuota')
                    ->from('DemandesBundle:Quota', 'q')
                    ->where('q.typeDemande = :Type')
                    ->setParameter('Type', $test['type'])
                    ->getQuery()
                    ->getOneOrNullResult();
            //dump($test['compter']);
            //dump($quota['nbreQuota']);

            if ($quota and ( $test['compter'] >= $quota['nbreQuota'])) {
                $array[] = $test['type'];
            }
        }//die;
        //dump($demandeAboutit);
        //dump($array);
        //var_dump($array);
        //die;
        //var_dump($demandeAboutit); die;
//var_dump(count($demandeEncours));
//var_dump($demandeAboutit);
// die;

        if ($demandeEncours and $demandeAboutit) {

            $qb = $this->getEntityManager()->createQueryBuilder();
            $qb
                    ->select(['c'])
                    ->from('DemandesBundle:TypeDemande', 'c')
                    ->where($queryBuilder->expr()->notIn('c.id', ':subQuery'))
                    ->andWhere($queryBuilder->expr()->notIn('c.id', ':subQuerys'))
                    ->andWhere('c.etat = 0')
                    ->setParameter('subQuery', $array)
                    ->setParameter('subQuerys', $demandeEncours);
            return $qb;
        } elseif ($demandeAboutit) {

            $qb = $this->getEntityManager()->createQueryBuilder();
            $qb
                    ->select(['c'])
                    ->from('DemandesBundle:TypeDemande', 'c')
                    ->where($queryBuilder->expr()->notIn('c.id', ':subQuery'))
                    ->andWhere('c.etat = 0')
                    ->setParameter('subQuery', $array);

            return $qb;
        } elseif ($demandeEncours) {
            $qb = $this->getEntityManager()->createQueryBuilder();
            $qb
                    ->select(['c'])
                    ->from('DemandesBundle:TypeDemande', 'c')
                    ->where($queryBuilder->expr()->notIn('c.id', ':subQuery'))
                    ->andWhere('c.etat = 0')
                    ->setParameter('subQuery', $demandeEncours);
            return $qb;
        } else {
            $qb = $this->getEntityManager()->createQueryBuilder();
            $qb
                    ->select(['c'])
                    ->from('DemandesBundle:TypeDemande', 'c')
                    ->where('c.etat = 0');
            return $qb;
        }
    }

    public function findTypeDemandePublic() {
        $qb = $this->getEntityManager()->createQueryBuilder()
                    ->select(['c'])
                    ->from('DemandesBundle:TypeDemande', 'c')
                    ->where('c.etat = 1');
            return $qb;
    }

}
